const allItems = [];
const ALERT_BEFORE_MINUTES = 15; 

// ดึง User ID และ Address
let userId = 'unknown';
let address = 'ไม่ระบุสถานที่'; 
try {
    const sheetData = $('Get row(s) in sheet').first().json;
    if (sheetData.userId) userId = sheetData.userId;
    if (sheetData.address) address = sheetData.address;
} catch(e) {}

// วนลูปสร้างรายการแจ้งเตือน
for (const item of items) {
    if (!item.json.data) continue;
    const timings = item.json.data.timings;

    // รายชื่อเวลาละหมาด
    const prayers = [
        { name: 'ฟัจร์ (Fajr)', time: timings.Fajr },
        { name: 'ดุฮฺริ (Dhuhr)', time: timings.Dhuhr },
        { name: 'อัสริ (Asr)', time: timings.Asr },
        { name: 'มัฆริบ (Maghrib)', time: timings.Maghrib },
        { name: 'อิชา (Isha)', time: timings.Isha }
    ];

    // --- แก้ไข: สร้างเวลาปัจจุบัน และ วันที่ แบบระบุ Timezone ไทย ---
    const now = new Date();

    // แปลงเวลาปัจจุบันให้เป็น String วันที่ของไทย (YYYY-MM-DD)
    // เพื่อป้องกันปัญหารันตอนตี 3 แล้วได้วันที่เมื่อวาน
    const thDateString = now.toLocaleDateString('en-CA', { timeZone: 'Asia/Bangkok' }); // format: 2025-12-04

    prayers.forEach(p => {
        // เอาเวลา (HH:mm) มาต่อกับวันที่ไทย และระบุ Offset +07:00 บังคับ
        // เช่น "2025-12-04T17:49:00+07:00"
        const timeStr = p.time.split(' ')[0]; // ตัด (WIB) ออก
        const isoString = `${thDateString}T${timeStr}:00+07:00`;

        const prayerDate = new Date(isoString); // ได้เวลาที่ถูกต้องแน่นอน 100%

        // คำนวณเวลาแจ้งเตือน (ถอยหลัง 15 นาที)
        const alertTime = new Date(prayerDate.getTime() - (ALERT_BEFORE_MINUTES * 60000));

        // Logic: ถ้าเวลาแจ้งเตือน ยังมาไม่ถึง (ในอนาคต) -> ให้สร้าง Task
        if (alertTime > now) {
            allItems.push({
                json: {
                    userId: userId,
                    address: address,
                    message: `🔔 อีก ${ALERT_BEFORE_MINUTES} นาที จะเข้าเวลา ${p.name} (${p.time}) เตรียมตัวได้เลยครับ`,
                    scheduledTime: alertTime.toISOString()
                }
            });
        }
    });
}

return allItems;

