                    message: `🔔 (เวลาใหม่) อีก ${ALERT_BEFORE_MINUTES} นาที จะเข้าเวลา ${p.name} (${p.time}) เตรียมตัวได้เลยครับ`,
                    scheduledTime: alertTime.toISOString()
                }
            });
        }
    });
}

return allItems;

